for q in ['\"barcodes.tsv.gz\" AND \"Mus musculus\"[Organism]', '\"matrix.mtx.gz\" AND \"Mus musculus\"[Organism]']:
    sr=json.load(urllib.request.urlopen('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?'+urllib.parse.urlencode({'db':'gds','term':q,'retmax':500,'retmode':'json'}), timeout=60))['esearchresult']
    print('query', q, sr['count'], len(sr['idlist']))
    ids += sr['idlist']; time.sleep(.5)
ids=list(dict.fromkeys(ids)); records=[]
for i in range(0,len(ids),40):
    for attempt in range(4):
        try:
            s=json.load(urllib.request.urlopen('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi?'+urllib.parse.urlencode({'db':'gds','id':','.join(ids[i:i+40]),'retmode':'json'}), timeout=60)); break
        except Exception as e:
            time.sleep(2*(attempt+1))
    else: continue
    for uid in ids[i:i+40]:
        d=s.get('result',{}).get(uid,{})
        acc=d.get('accession','')
        if acc.startswith('GSE'):
            records.append({'acc':acc,'title':d.get('title','').replace('\\t',' ')})
    time.sleep(.5)
records=list({r['acc']:r for r in records}.values())
