def list_barcodes(r):
    acc=r['acc']; base=f'https://ftp.ncbi.nlm.nih.gov/geo/series/GSE{acc[3:6]}nnn/{acc}/suppl/'
    try: html=urllib.request.urlopen(base, timeout=15).read().decode(errors='replace')
    except Exception: return []
    return [(r, base+urllib.parse.quote(urllib.parse.unquote(h)), urllib.parse.unquote(h)) for h in re.findall(r'href=\"(["'^"]+)"'"', html) if 'barcode' in urllib.parse.unquote(h).lower() and not urllib.parse.unquote(h).endswith('/')]
