with concurrent.futures.ThreadPoolExecutor(max_workers=12) as ex:
    for part in ex.map(list_barcodes, records): barfiles.extend(part)
print('barfiles',len(barfiles))

def check(item):
    r,url,name=item
    try:
        data=urllib.request.urlopen(url, timeout=30).read()
        if name.endswith('.gz'): data=gzip.decompress(data)
        vals=[ln.split('\\t')[0] for ln in data.decode(errors='replace').splitlines() if ln.strip()]
        if len(vals)==target_count and vals[:10]==target_first and vals[-10:]==target_last:
            return ('MATCH', r['acc'], name, r['title'], url)
        if len(vals)==target_count:
            return ('COUNT', r['acc'], name, vals[:3], vals[-3:], r['title'], url)
    except Exception: pass
for item in barfiles:
    res=check(item)
    if res: print(res)
