import h5py


def describe(obj):
    if isinstance(obj, h5py.Dataset):
        return "Dataset", obj.shape, str(obj.dtype)
    if isinstance(obj, h5py.Group):
        return "Group", "", ""
    return type(obj).__name__, "", ""


def main():
    in_path = sys.argv[1]
    out_path = sys.argv[2]
    with h5py.File(in_path, "r") as f, open(out_path, "w") as out:
        out.write("path\tkind\tshape\tdtype\tattrs\n")

        def visit(name, obj):
            kind, shape, dtype = describe(obj)
            attrs = {}
            try:
                attrs = {str(k): repr(v) for k, v in obj.attrs.items()}
            except Exception:
                pass
            out.write(
                "\t".join(
                    [
                        "/" + name if name else "/",
                        kind,
                        str(shape),
                        dtype,
                        repr(attrs),
                    ]
                )
                + "\n"

